-- The queries of module `store_server`, for the bc-telemetry layout on PostgreSQL.
--
-- Generated by bc-telemetry-gen. Do not edit.
-- Each statement is written for Grafana's PostgreSQL data source: $__timeFilter and
-- $__timeGroupAlias are its macros, expanded to a dashboard's time range and interval.

-- cart-size-avg: Average cart size at checkout
-- unit: none
SELECT $__timeGroupAlias(time, '5m'),
       avg(value) AS value
FROM telemetry."metric__store_server__cart_size"
WHERE $__timeFilter(time)
GROUP BY 1
ORDER BY 1;

-- checkout-p95: 95th-percentile request latency per route over five minutes
-- unit: ms
SELECT $__timeGroupAlias(time, '5m'),
       "route",
       percentile_cont(0.95) WITHIN GROUP (ORDER BY value) AS value
FROM telemetry."metric__store_server__request_duration"
WHERE $__timeFilter(time)
GROUP BY 1, "route"
ORDER BY 1;

-- checkout-rate: Checkouts started per second
-- unit: per second
SELECT $__timeGroupAlias(time, '1m'),
       count(*)::double precision / 60 AS value
FROM telemetry."span__store_server__checkout"
WHERE $__timeFilter(time)
GROUP BY 1
ORDER BY 1;

-- declines-by-processor: Declined authorizations per day, by the processor's code
-- unit: none
SELECT $__timeGroupAlias(time, '1d'),
       "processor_code",
       count(*) AS value
FROM telemetry."error__payments__authorization_declined"
WHERE $__timeFilter(time)
GROUP BY 1, "processor_code"
ORDER BY 1;

-- failed-orders: Failed orders per hour, by reason
-- unit: none
SELECT $__timeGroupAlias(time, '1h'),
       "reason",
       count(*) AS value
FROM telemetry."log__store_server__order_failed"
WHERE $__timeFilter(time)
GROUP BY 1, "reason"
ORDER BY 1;

-- orders-per-second: Orders placed per second
-- unit: per second
SELECT $__timeGroupAlias(time, '30s'),
       sum(value) / 30 AS value
FROM telemetry."metric__store_server__orders_placed"
WHERE $__timeFilter(time)
GROUP BY 1
ORDER BY 1;

-- records of log order_failed: An order that reached checkout and did not complete
SELECT time, body, severity AS level, "order_id", "reason"
FROM telemetry."log__store_server__order_failed"
WHERE $__timeFilter(time)
ORDER BY time DESC;
